/**
 * The lab book's sections for a level. Task is the printed brief. Theory meets the parts first
 * (one spread per part: what each leg and marking means), then the level's class step by step
 * with its live labs, then the check. Math is the formulas, a worked example and a practice
 * question, generated by the exam drills (so the numbers are always the solver's).
 */
import { GENERATORS } from '../drills/generators';
import { classForLevel } from '../learn/classes';
import type { LearnClass, Step } from '../learn/types';
import type { LevelDef } from '../levels/types';

export type Section = 'task' | 'theory' | 'math';
export const SECTIONS: Section[] = ['task', 'theory', 'math'];

export type PartId = 'led' | 'resistor' | 'breadboard' | 'multimeter' | 'capacitor' | 'button' | 'battery' | 'transistor'
  | 'diode' | 'pot' | 'mosfet' | 'regulator' | 'chip' | 'toggle';

export interface PartExplainer {
  id: PartId;
  name: string;
  /** One line: what it does. */
  job: string;
  /** Callouts on the model: what each bit is. */
  facts: { label: string; text: string }[];
}

export interface Formula {
  name: string;
  /** Shown big, e.g. "V = I × R". */
  expr: string;
  /** What each symbol means. */
  terms: [string, string][];
  /** When to use it, in one line. */
  when: string;
}

export type Spread =
  | { kind: 'part'; part: PartExplainer }
  | { kind: 'step'; cls: LearnClass; step: Step; index: number }
  | { kind: 'check'; cls: LearnClass }
  | { kind: 'formulas'; formulas: Formula[] }
  | { kind: 'worked'; generator: string; seed: number }
  | { kind: 'practice'; generator: string };

