/** A stable seed per level so the worked example is the same each time you open it. */
const seedOf = (id: string) => [...id].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);

export function spreads(level: LevelDef, section: Section): Spread[] {
  const plan = LEVEL[level.id] ?? { parts: [], formulas: ['ohm'], generators: ['ohm'] };
  if (section === 'theory') {
    const cls = classForLevel(level.id);
    return [
      ...plan.parts.map((p) => ({ kind: 'part' as const, part: PARTS[p] })),
      ...(cls ? cls.steps.map((step, index) => ({ kind: 'step' as const, cls, step, index })) : []),
      ...(cls ? [{ kind: 'check' as const, cls }] : []),
    ];
  }
  if (section === 'math') {
    const gens = plan.generators.filter((g) => GENERATORS.some((x) => x.id === g));
    return [
      { kind: 'formulas', formulas: plan.formulas.map((f) => FORMULAS[f]!).filter(Boolean) },
      ...gens.map((g) => ({ kind: 'worked' as const, generator: g, seed: seedOf(level.id + g) })),
      { kind: 'practice', generator: gens[0] ?? 'ohm' },
    ];
  }
  return [];
}
